BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT119-S2-Q7$batch11$ AND q.stimulus=$batch11$Although instinct enables organisms to make complex responses to stimuli, instinctual behavior involves no reasoning and requires far fewer nerve cells than does noninstinctual (also called flexible) behavior. A brain mechanism capable of flexible behavior must have a large number of neurons, and no insect brain has yet reached a size capable of providing a sufficiently large number of neurons.$batch11$ AND q.prompt=$batch11$Which one of the following can be properly inferred from the statements above?$batch11$ AND q.correct_choice=$batch11$B$batch11$) THEN RAISE EXCEPTION 'Question changed: PT119-S2-Q7'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s WHERE s.explanation_id=$batch11$a343e345-371c-419c-bee8-15c49d6371ff$batch11$) <> 3 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n WHERE n.explanation_id=$batch11$a343e345-371c-419c-bee8-15c49d6371ff$batch11$) <> 0 THEN RAISE EXCEPTION 'Explanation changed: PT119-S2-Q7'; END IF; END $guard$;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch11$A$batch11$, $batch11$Large brains make flexible behavior possible. Nothing says such organisms usually use it.$batch11$), ($batch11$B$batch11$, $batch11$Flexible behavior needs many neurons, and no insect brain has enough. The only other kind of behavior is instinctual, so insect behavior is all instinctual.$batch11$), ($batch11$C$batch11$, $batch11$Being larger than an insect's brain doesn't mean a brain has enough neurons for flexible behavior.$batch11$), ($batch11$D$batch11$, $batch11$A large number of neurons is required for flexible behavior, not enough for it. A large brain isn't guaranteed to be equipped.$batch11$), ($batch11$E$batch11$, $batch11$Insects are limited to instinct, but other organisms could be too. Nothing makes insect-sized brains the only ones.$batch11$)) v(letter,body) WHERE q.qid=$batch11$PT119-S2-Q7$batch11$ AND e.id=$batch11$a343e345-371c-419c-bee8-15c49d6371ff$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
